css:
.loader { --accent: var(--loader-color); width: var(--loader-size); height: calc(var(--loader-size) * .62); display: flex; align-items: flex-end; gap: calc(var(--loader-size) * .06); }
.loader span { flex: 1; background: var(--accent); border-radius: calc(var(--loader-size) * .02); opacity: .22; animation: signal calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader span:nth-child(1) { height: 28%; animation-delay: 0s; }
.loader span:nth-child(2) { height: 52%; animation-delay: calc(var(--loader-speed) * .15); }
.loader span:nth-child(3) { height: 76%; animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(4) { height: 100%; animation-delay: calc(var(--loader-speed) * .45); }
@keyframes signal { 0%, 100% { opacity: .22; } 50% { opacity: 1; } }
